parameters.jsonOutput:
={{ JSON.stringify((() => {
  const f = $json.fields || {};
  const leer = (texto, defecto) => {
    try { return texto ? JSON.parse(texto) : defecto; } catch (e) { return defecto; }
  };
  const datos = leer(f['Datos clave'], {});
  const resumen = leer(f['Resumen consolidado'], null);
  const estado = f['Estado del caso'] || 'NUEVO';
  const vacante = datos.ultima_vacante || {};
  const lineas = [];
  if (datos.user_name) lineas.push(`La persona se llama ${datos.user_name}.`);
  if (estado !== 'NUEVO') lineas.push(`Estado de su última solicitud: ${estado}.`);
  if (resumen) {
    lineas.push(`Resumen de la charla anterior: ${resumen.asunto_principal}`);
    if ((resumen.puntos_clave || []).length) lineas.push(`Puntos clave: ${resumen.puntos_clave.join('; ')}`);
    if (resumen.accion_requerida && resumen.accion_requerida !== 'ninguna') lineas.push(`Pendiente: ${resumen.accion_requerida}`);
  }
  if (datos.cv_url) lineas.push(`CV guardado: ${datos.cv_url}`);
  if (datos.criterios_url) lineas.push(`Criterios guardados: ${datos.criterios_url}`);
  else if (datos.criterios_resuelto) lineas.push('Criterios: ya respondió que no los comparte.');
  if (vacante.empresa) lineas.push(`Última vacante analizada: ${vacante.rol} en ${vacante.empresa}, match ${vacante.match}.`);
  return {
    memoria_id: $json.id,
    Session_ID: $('Identificar sesión').first().json.Session_ID,
    chatInput: $('Identificar sesión').first().json.chatInput,
    estado,
    intercambios: Number(f['Intercambios']) || 0,
    datos,
    resumen,
    bloque_contexto: lineas.length
      ? ['[INICIO DE CONTEXTO COMPARTIDO]', ...lineas, '[FIN DEL CONTEXTO COMPARTIDO]'].join('\n')
      : ''
  };
})()) }}

={{ JSON.stringify((() => {
  const m = $('Memoria').first().json;
  const datos = { ...m.datos };
  const rec = $('Recepcionista').isExecuted ? $('Recepcionista').first().json.output : null;
  if (rec) {
    if (rec.cv_url) datos.cv_url = rec.cv_url;
    if (rec.criterios_url) datos.criterios_url = rec.criterios_url;
    if (rec.criterios_resuelto) datos.criterios_resuelto = true;
  }
  let estado;
  if ($('Respuesta análisis').isExecuted) {
    const d = $('Resultado Analista').first().json.data;
    estado = 'VACANTE_ANALIZADA';
    datos.ultima_vacante = {
      empresa: d.empresa,
      rol: d.rol,
      elegibilidad: d.elegibilidad,
      encaje_criterios: (d.encaje_criterios || {}).resultado || 'no_evaluado',
      match: d.match
    };
    datos.vacantes_analizadas = (datos.vacantes_analizadas || 0) + 1;
    if (d.nombre_candidato) datos.user_name = d.nombre_candidato;
  } else if ($('Respuesta carta').isExecuted) {
    estado = 'CARTA_REDACTADA';
    datos.cartas_redactadas = (datos.cartas_redactadas || 0) + 1;
  } else if ($('Respuesta error').isExecuted || $('Respuesta de falla al candidato').isExecuted) {
    estado = 'ERROR';
  } else if (rec && rec.listo && rec.intent === 'FUERA_DE_ALCANCE') {
    estado = 'FUERA_DE_ALCANCE';
  } else {
    estado = 'FALTA_DATO';
  }
  return {
    memoria_id: m.memoria_id,
    estado,
    datos,
    datos_clave: JSON.stringify(datos),
    intercambios: m.intercambios + 1,
    respuesta: $json.output
  };
})()) }}

